# -*- coding: utf-8 -*-
# IDUM 10: самопроверка выборки 40 задач + сверка спорных со страницами учебника (PDF). 26.09
P = {}
S = "IDUM 10 (страницы учебника PDF) + пересчёт, 26.09"
def E(t, why, **kw): P[t] = dict(why=why, src=S, **kw)
E("G10_TB_1_9_2", "вариант «x = −1/6; y = 7,25» совпадал с ключом (29/4 = 7,25) — верный ответ в другой записи, закрыт", drop=[1])
E("G10_TB_2_4_3_b", "вариант «[−2/3; 3,5) ∪ [4; 5)» совпадал с ключом (7/2 = 3,5) — закрыт", drop=[2])
E("G10_TB_1_6_2_7", "в LaTeX-условии корень захватил «+1»: в учебнике (упр. 2 g), стр. 52) g(x) = −√x + 1; ключ «отражение относительно Ox и сдвиг вверх на 1» верен для условия учебника",
  qrep=(r"g(x)=-\sqrt{x+1}", r"g(x)=-\sqrt{x}+1"))
E("G10_TB_2_6_5_b", "в условии корень 6-й степени заменён кубическим (учебник, упр. 5 b), стр. 92: ⁶√x − ⁶√y = 1), ключ (11025; 9604) относился к искажённому условию и для условия учебника неверен (√11025 − √9604 = 7, но ⁶√11025 − ⁶√9604 ≠ 1); a = ⁶√x, b = ⁶√y: a − b = 1, a³ − b³ = 7 ⇒ b = 1, a = 2 ⇒ (64; 1); вариант «(64; 1)» был верным ответом среди неверных — закрыт",
  q=r"Решите систему уравнений: $$\begin{cases} \sqrt{x} - \sqrt{y} = 7, \\ \sqrt[6]{x} - \sqrt[6]{y} = 1 \end{cases}$$", k=r"$(64; 1)$", drop=[0])
E("G10_TB_2_6_5_a", "в условии корень 6-й степени заменён кубическим (учебник, упр. 5 a), стр. 92: ⁶√x + ⁶√y = 3), ключ «нет действительных решений» был для искажённого условия; a + b = 3, a³ + b³ = 9 ⇒ ab = 2 ⇒ {1; 2} ⇒ (1; 64) и (64; 1); вариант «x = 1, y = 64» был верным ответом среди неверных — закрыт",
  q=r"Решите систему уравнений: $$\begin{cases} \sqrt{x} + \sqrt{y} = 9, \\ \sqrt[6]{x} + \sqrt[6]{y} = 3 \end{cases}$$", k=r"$(1; 64)$ и $(64; 1)$", drop=[1],
  dadd=[("нет действительных решений", "Ученик решил систему с кубическими корнями вместо корней шестой степени.")])
N = "все три неверных варианта были пустыми (None) — по решению владельца добавлены неверные варианты с описанием типичной ошибки; ключ пересчитан: "
E("G10_TB_3_4_3_1", N + "log по основанию 1/5 убывает, 10 < 15 < 20 ⇒ a > b > c",
  dnew={0: (r"$a, b, c$", "Ученик не учёл, что логарифм по основанию 1/5 — убывающая функция, и упорядочил числа как аргументы."),
        1: (r"$c, a, b$", "Ученик верно поставил c первым, но ошибся при сравнении a и b."),
        2: (r"$b, a, c$", "Ученик сравнивал числа наугад, не используя монотонность логарифмической функции.")})
for t, f, ev, od in [("G10_TB_1_5_1_g", "1 − ∛x", "∛x — нечётная функция, но слагаемое 1 — чётное", "f(−x) = 1 + ∛x не равно ни f(x), ни −f(x)"),
                     ("G10_TB_1_5_1_c", "x² + x", "x² — чётная, x — нечётная", "f(−x) = x² − x не равно ни f(x), ни −f(x)"),
                     ("G10_TB_1_5_1_f", "3x³ + 2x² + 1", "3x³ — нечётное слагаемое, 2x² + 1 — чётные", "f(−x) = −3x³ + 2x² + 1 не равно ни f(x), ни −f(x)")]:
    E(t, N + od, dnew={0: ("чётная", f"Ученик учёл только чётные слагаемые функции f(x) = {f}."), 1: ("нечётная", f"Ученик учёл только нечётные слагаемые функции f(x) = {f}."),
                       2: ("и чётная, и нечётная", f"Ученик решил, что сумма чётной и нечётной частей обладает обоими свойствами ({ev}).")})
E("G10_TB_3_1_2_3", N + "(1/3)^x принимает все положительные значения, поэтому −(1/3)^x — все отрицательные",
  dnew={0: (r"$(0; +\infty)$", "Ученик не учёл знак минус перед степенью."), 1: (r"$(-\infty; 0]$", "Ученик включил 0, хотя (1/3)^x никогда не равно нулю."),
        2: (r"$(-\infty; +\infty)$", "Ученик указал область определения вместо множества значений.")})
